// HAND-IMPLEMENTED SUBJECT — behavior A1 (zfa:tdd: A1:hand).
//
// behavior_id: A1
// source_criterion: AC-1
// description: the resolution succeeds: no family member in the graph demands the Flutter SDK, neither as an `environment: flutter:` constraint nor as a `flutter: sdk: flutter` dependency.
//
// The scenario reads the family's shipped pubspecs — the real manifest — so
// the check fails the moment a member takes a dependency on the Flutter SDK
// again.
//
// Two pubspec keys make a package unreachable for a consumer that has no
// Flutter SDK beside it: an `environment: flutter:` constraint, and a
// `flutter: {sdk: flutter}` dependency. The plugin manifest (`flutter:
// plugin: ...`) is a different key and pub never reads it, so it is not a
// requirement — the scenario only looks at the two keys pub does read.
//
// The [layout] seam lets a test drive the scenario with a deliberately
// broken family, so the failure paths are covered too and not only the
// happy path.
//
// ignore_for_file: non_constant_identifier_names
library;

import 'dart:convert';

import 'package:html_to_markdown_ffi_workspace/tdd/001-zero-touch-native-distribution/family_layout.dart';

/// How one family member asks for the Flutter SDK.
class FlutterSdkRequirement {
  /// The member's package name.
  final String packageName;

  /// Whether the member declares an `environment: flutter:` constraint.
  final bool hasEnvironmentConstraint;

  /// Whether the member depends on the Flutter SDK.
  final bool hasSdkDependency;

  const FlutterSdkRequirement({
    required this.packageName,
    required this.hasEnvironmentConstraint,
    required this.hasSdkDependency,
  });
}

/// The lines of the block under the top-level [key] of a pubspec.
///
/// A block ends at the next line that starts at column zero — that is where
/// the next top-level key begins. Blank lines are skipped so a block that
/// ends with one is still closed correctly.
List<String> topLevelBlock(String pubspec, String key) {
  final lines = const LineSplitter().convert(pubspec);
  final block = <String>[];
  var inside = false;
  for (final line in lines) {
    if (!inside) {
      if (line.startsWith('$key:')) inside = true;
      continue;
    }
    if (line.trim().isEmpty) continue;
    if (!_indentedLine.hasMatch(line)) break;
    block.add(line);
  }
  return block;
}

/// Whether a line is indented — that is, whether it belongs to a block
/// rather than to the top level of the manifest.
final RegExp _indentedLine = RegExp('^[ \\t]');

/// The number of columns a line is indented by.
int indentOf(String line) {
  var columns = 0;
  for (final unit in line.codeUnits) {
    if (unit != 0x20 && unit != 0x09) break;
    columns++;
  }
  return columns;
}

/// Whether a pubspec's `environment:` block constrains the Flutter SDK.
bool declaresFlutterEnvironmentConstraint(String pubspec) {
  final block = topLevelBlock(pubspec, 'environment');
  return block.any((line) => RegExp('^\\s+flutter:\\s*\\S').hasMatch(line));
}

/// Whether a pubspec's `dependencies:` block depends on the Flutter SDK.
bool dependsOnFlutterSdk(String pubspec) {
  final block = topLevelBlock(pubspec, 'dependencies');
  for (var i = 0; i < block.length; i++) {
    if (!RegExp('^\\s+flutter:\\s*\$').hasMatch(block[i])) continue;
    // The dependency is a map: its own value block follows the key, and the
    // `sdk: flutter` has to live in that block — a `sdk: flutter` that
    // belongs to the next dependency is that dependency's business.
    final keyIndent = indentOf(block[i]);
    for (var j = i + 1; j < block.length; j++) {
      final line = block[j];
      if (indentOf(line) <= keyIndent) break;
      if (RegExp('^\\s+sdk:\\s*flutter\\s*\$').hasMatch(line)) return true;
    }
  }
  return false;
}

/// What every family member asks for.
List<FlutterSdkRequirement> readFlutterSdkRequirements(RepoLayout repo) {
  return <FlutterSdkRequirement>[
    for (final packageName in familyPackages)
      if (repo.memberPubspecOrNull(packageName) case final pubspec?)
        FlutterSdkRequirement(
          packageName: packageName,
          hasEnvironmentConstraint:
              declaresFlutterEnvironmentConstraint(pubspec),
          hasSdkDependency: dependsOnFlutterSdk(pubspec),
        ),
  ];
}

/// Scenario runner for behavior A1.
///
/// Returns the violations found; an empty list means the scenario holds.
///
/// When [layout] is given it replaces the repository the scenario reads.
List<String> subject_a1({RepoLayout? layout}) {
  final repo = layout ?? RepoLayout.repository();
  final violations = <String>[];

  for (final requirement in readFlutterSdkRequirements(repo)) {
    if (requirement.hasEnvironmentConstraint) {
      violations.add(
        '${requirement.packageName} constrains the Flutter SDK in its '
        '`environment:` — a consumer with a plain Dart SDK cannot resolve '
        'it.',
      );
    }
    if (requirement.hasSdkDependency) {
      violations.add(
        '${requirement.packageName} depends on the Flutter SDK — a consumer '
        'with a plain Dart SDK cannot resolve it.',
      );
    }
  }

  return violations;
}
